<script setup>
import {onMounted,ref,computed} from 'vue'
import PageHeader from '../components/PageHeader.vue'
import GlassWindow from '../components/GlassWindow.vue'
import ResourceGrants from '../components/ResourceGrants.vue'
import NotificationPreferences from '../components/NotificationPreferences.vue'
import EntraSettings from '../components/EntraSettings.vue'
import EventExportSettings from '../components/EventExportSettings.vue'
import {applyTheme,localTheme,normalizeTheme,setLocalTheme} from '../lib/theme.js'
import {api,session,download} from '../lib/api.js'
const tab=ref('credentials'),credentials=ref([]),users=ref([]),invites=ref([]),teams=ref([]),nodeGroups=ref([]),audit=ref([]),agents=ref([]),nodes=ref([]),error=ref(''),message=ref(''),formOpen=ref(false),credentialForm=ref({name:'',type:'local',username:'',password:'',visibility:'private',priority:100}),userForm=ref({email:'',password:'',role:'auditor'}),inviteForm=ref({email:'',role:'auditor',teamId:''}),inviteResult=ref(null),teamName=ref(''),enrollNode=ref(''),token=ref(null)
const me=ref(null),totpSetup=ref(null),totpCode=ref(''),disablePassword=ref(''),disableCode=ref('')
const newEmail=ref('')
const currentPassword=ref(''),newPassword=ref(''),confirmPassword=ref('')
const serverTheme=ref('system'),browserTheme=ref(localTheme())
const uploadingAvatar=ref(false)
const portalBrand=ref({companyName:'WinFire Secure',imageUrl:null}),portalBrandBusy=ref(false)
const mfaPromptSettings=ref({failureMode:'closed',failOpenMinutes:5}),mfaPromptApproval=ref(''),mfaPromptBusy=ref(false)
const trainingSettings=ref({newHostTrainingDays:30,progressiveLearning:{enabled:false,startDays:15,intervalHours:24}}),trainingSaving=ref(false)
const directorySettings=ref({url:'',baseDn:'',bindCredentialId:'',nodeCredentialId:null,actionCredentialId:null,enabled:false,syncIntervalMinutes:60,allowLdapFallback:false}),directoryBusy=ref(false),directoryResult=ref(null),directoryApproval=ref(''),approvedDirectory=ref({url:'',bindCredentialId:''})
const observabilitySettings=ref({logRetentionDays:90,dnsRefreshHours:24,eventCompactHours:24,hideLoopbackEvents:true,ignoreLoopbackIngest:false}),observabilitySaving=ref(false)
const auditFilters=ref({q:'',action:'',entityType:'',actor:'',from:'',to:''}),auditPage=ref(1),auditPageSize=ref(100),auditTotal=ref(0),auditSortBy=ref('time'),auditSortDir=ref('desc'),auditLoading=ref(false)
const auditPages=computed(()=>Math.max(1,Math.ceil(auditTotal.value/auditPageSize.value)))
function auditQuery(extra={}){const params={page:auditPage.value,pageSize:auditPageSize.value,sortBy:auditSortBy.value,sortDir:auditSortDir.value,...auditFilters.value,...extra};for(const key of ['from','to'])if(params[key])params[key]=new Date(params[key]).toISOString();return new URLSearchParams(Object.entries(params).filter(([,value])=>value!==''&&value!==null)).toString()}
async function loadAudit(){auditLoading.value=true;try{const result=await api(`/audit/search?${auditQuery()}`);audit.value=result.items;auditTotal.value=result.total}catch(e){error.value=e.message}finally{auditLoading.value=false}}
function auditSearch(){auditPage.value=1;loadAudit()}
function auditSort(column){if(auditSortBy.value===column)auditSortDir.value=auditSortDir.value==='asc'?'desc':'asc';else{auditSortBy.value=column;auditSortDir.value=column==='time'?'desc':'asc'}auditSearch()}
function auditMove(page){if(page<1||page>auditPages.value)return;auditPage.value=page;loadAudit()}
async function exportAudit(format){try{await download(`/audit/search?${auditQuery({export:format})}`,`audit-trail.${format}`)}catch(e){error.value=e.message}}
const userToDelete=ref(null),deleteConfirmOpen=ref(false)
const credentialWindowOpen=ref(false),selectedCredential=ref(null),credentialTargetKind=ref('node'),credentialNodeId=ref(''),credentialGroupId=ref(''),credentialNewPassword=ref(''),credentialTestResult=ref(null),credentialBusy=ref(false)
const origin=location.origin
const isAdmin=computed(()=>['owner','admin'].includes(session.user?.role))
const fallbackApprovalRequired=computed(()=>directorySettings.value.allowLdapFallback&&(!directorySettings.value.ldapFallbackApprovedAt||directorySettings.value.url!==approvedDirectory.value.url||directorySettings.value.bindCredentialId!==approvedDirectory.value.bindCredentialId))
const canManageUser=user=>isAdmin.value&&user.id!==session.user?.id&&(user.role!=='owner'||session.user?.role==='owner')
const canManageCredential=credential=>!!credential?.canWrite
async function load(){try{const requests=[api('/credentials'),api('/teams'),api(`/audit/search?${auditQuery()}`),api('/agents'),api('/nodes'),api('/settings/training'),api('/node-groups')];if(isAdmin.value)requests.push(api('/settings/directory'),api('/settings/observability'),api('/users'),api('/invites'),api('/portal-branding'),api('/settings/mfa-prompt'));const result=await Promise.all(requests);[credentials.value,teams.value,,agents.value,nodes.value,trainingSettings.value,nodeGroups.value]=result;audit.value=result[2].items;auditTotal.value=result[2].total;if(isAdmin.value){directorySettings.value=result[7];approvedDirectory.value={url:result[7].url,bindCredentialId:result[7].bindCredentialId};observabilitySettings.value=result[8];users.value=result[9];invites.value=result[10];portalBrand.value=result[11];mfaPromptSettings.value=result[12]}error.value=''}catch(e){error.value=e.message}}
async function saveObservability(){observabilitySaving.value=true;error.value='';try{observabilitySettings.value=await api('/settings/observability',{method:'PATCH',body:{logRetentionDays:Number(observabilitySettings.value.logRetentionDays),dnsRefreshHours:Number(observabilitySettings.value.dnsRefreshHours),eventCompactHours:Number(observabilitySettings.value.eventCompactHours),hideLoopbackEvents:observabilitySettings.value.hideLoopbackEvents,ignoreLoopbackIngest:observabilitySettings.value.ignoreLoopbackIngest}});message.value='Logs and DNS settings saved'}catch(e){error.value=e.message}finally{observabilitySaving.value=false}}
async function saveTraining(){trainingSaving.value=true;error.value='';try{const settings=trainingSettings.value;trainingSettings.value=await api('/settings/training',{method:'PATCH',body:{newHostTrainingDays:Number(settings.newHostTrainingDays),progressiveLearning:{enabled:settings.progressiveLearning.enabled,startDays:Number(settings.progressiveLearning.startDays),intervalHours:Number(settings.progressiveLearning.intervalHours)}}});message.value='New-host training settings saved'}catch(e){error.value=e.message}finally{trainingSaving.value=false}}
async function saveDirectory(silent=false){directoryBusy.value=true;error.value='';try{const settings=directorySettings.value;directorySettings.value=await api('/settings/directory',{method:'PATCH',body:{url:settings.url,baseDn:settings.baseDn,bindCredentialId:settings.bindCredentialId,nodeCredentialId:settings.nodeCredentialId||null,enabled:settings.enabled,syncIntervalMinutes:Number(settings.syncIntervalMinutes),allowLdapFallback:settings.allowLdapFallback,...(fallbackApprovalRequired.value?{ldapFallbackApproval:directoryApproval.value}:{})}});approvedDirectory.value={url:directorySettings.value.url,bindCredentialId:directorySettings.value.bindCredentialId};directoryApproval.value='';if(!silent)message.value='Active Directory settings saved';return true}catch(e){error.value=e.message;return false}finally{directoryBusy.value=false}}
async function saveDirectoryActionCredential(){directoryBusy.value=true;error.value='';try{directorySettings.value=await api('/settings/directory/action-credential',{method:'PATCH',body:{credentialId:directorySettings.value.actionCredentialId||null}});message.value='AD account-control credential saved'}catch(e){error.value=e.message}finally{directoryBusy.value=false}}
async function testDirectory(){message.value='';if(!await saveDirectory(true))return;directoryBusy.value=true;error.value='';try{directoryResult.value=await api('/directory/test',{method:'POST',body:{}});message.value=`Directory bind and search base validated over ${directoryResult.value.transport==='ldap'?'LDAP 389 (approved fallback)':'LDAPS'}`}catch(e){error.value=e.message}finally{directoryBusy.value=false}}
async function syncDirectoryNow(){message.value='';if(!await saveDirectory(true))return;directoryBusy.value=true;error.value='';try{directoryResult.value=await api('/directory/sync',{method:'POST',body:{}});message.value=`Directory sync completed over ${directoryResult.value.transport==='ldap'?'LDAP 389 (approved fallback)':'LDAPS'}: ${directoryResult.value.created} added, ${directoryResult.value.updated} updated`;await load()}catch(e){await load();error.value=e.message}finally{directoryBusy.value=false}}
async function createCredential(){try{await api('/credentials',{method:'POST',body:credentialForm.value});formOpen.value=false;credentialForm.value={name:'',type:'local',username:'',password:'',visibility:'private',priority:100};await load()}catch(e){error.value=e.message}}
function openCredential(credential){selectedCredential.value=credential;credentialTargetKind.value='node';credentialNodeId.value='';credentialGroupId.value='';credentialNewPassword.value='';credentialTestResult.value=null;credentialWindowOpen.value=true}
async function assignCredential(){if(!selectedCredential.value)return;const body=credentialTargetKind.value==='node'?{nodeId:credentialNodeId.value}:{nodeGroupId:credentialGroupId.value};if(!Object.values(body)[0])return;credentialBusy.value=true;error.value='';try{const result=await api(`/credentials/${selectedCredential.value.id}/assignments`,{method:'POST',body});message.value=result.alreadyAssigned?'Credential already assigned':'Credential assigned to '+credentialTargetKind.value}catch(e){error.value=e.message}finally{credentialBusy.value=false}}
async function testCredential(){if(!selectedCredential.value||!credentialNodeId.value)return;credentialBusy.value=true;error.value='';credentialTestResult.value=null;try{credentialTestResult.value=await api(`/credentials/${selectedCredential.value.id}/test`,{method:'POST',body:{nodeId:credentialNodeId.value}})}catch(e){error.value=e.message}finally{credentialBusy.value=false}}
async function rotateCredential(){if(!selectedCredential.value||!credentialNewPassword.value)return;credentialBusy.value=true;error.value='';try{await api(`/credentials/${selectedCredential.value.id}`,{method:'PATCH',body:{password:credentialNewPassword.value}});credentialNewPassword.value='';message.value='Credential password rotated';await load()}catch(e){error.value=e.message}finally{credentialBusy.value=false}}
async function createUser(){try{await api('/users',{method:'POST',body:userForm.value});userForm.value={email:'',password:'',role:'auditor'};message.value='User created';await load()}catch(e){error.value=e.message}}
async function createInvite(){try{inviteResult.value=await api('/invites',{method:'POST',body:{email:inviteForm.value.email,role:inviteForm.value.role,teamId:inviteForm.value.teamId||undefined}});inviteForm.value={email:'',role:'auditor',teamId:''};message.value=inviteResult.value.delivered?'Invitation emailed':'Invitation created; copy the link below';await load()}catch(e){error.value=e.message}}
async function revokeSessions(user){try{await api(`/users/${user.id}/revoke-sessions`,{method:'POST',body:{}});message.value=`Sessions revoked for ${user.email}`;await load()}catch(e){error.value=e.message}}
async function setSuspended(user){try{await api(`/users/${user.id}`,{method:'PATCH',body:{suspended:!user.suspended}});message.value=`${user.email} ${user.suspended?'restored':'suspended'}`;await load()}catch(e){error.value=e.message}}
async function deleteUser(){if(!userToDelete.value)return;const user=userToDelete.value;try{await api(`/users/${user.id}`,{method:'DELETE'});userToDelete.value=null;deleteConfirmOpen.value=false;message.value=`${user.email} deleted`;await load()}catch(e){error.value=e.message}}
function confirmDeleteUser(user){userToDelete.value=user;deleteConfirmOpen.value=true}
async function createTeam(){try{await api('/teams',{method:'POST',body:{name:teamName.value}});teamName.value='';await load()}catch(e){error.value=e.message}}
async function createToken(){try{token.value=await api('/agents/enrollment-tokens',{method:'POST',body:{nodeId:enrollNode.value}})}catch(e){error.value=e.message}}
async function revokeAgent(agent){try{await api(`/agents/${agent.id}/revoke`,{method:'POST',body:{}});message.value='Agent certificate revoked';await load()}catch(e){error.value=e.message}}
async function beginTotp(){try{totpSetup.value=await api('/auth/totp/setup',{method:'POST',body:{}});error.value=''}catch(e){error.value=e.message}}
async function confirmTotp(){try{await api('/auth/totp/confirm',{method:'POST',body:{code:totpCode.value}});me.value=await api('/auth/me');totpSetup.value=null;totpCode.value='';message.value='Authenticator enabled'}catch(e){error.value=e.message}}
async function removeTotp(){try{await api('/auth/totp/disable',{method:'POST',body:{password:disablePassword.value,code:disableCode.value}});me.value=await api('/auth/me');disablePassword.value='';disableCode.value='';message.value='Authenticator disabled'}catch(e){error.value=e.message}}
async function savePortalBrand(){portalBrandBusy.value=true;error.value='';try{portalBrand.value=await api('/settings/portal-branding',{method:'PATCH',body:{companyName:portalBrand.value.companyName}});message.value='Portal company name saved'}catch(e){error.value=e.message}finally{portalBrandBusy.value=false}}
async function saveMfaPromptSettings(){mfaPromptBusy.value=true;error.value='';try{mfaPromptSettings.value=await api('/settings/mfa-prompt',{method:'PATCH',body:{failureMode:mfaPromptSettings.value.failureMode,failOpenMinutes:Number(mfaPromptSettings.value.failOpenMinutes),approval:mfaPromptApproval.value}});mfaPromptApproval.value='';message.value='Automatic MFA prompt fallback saved'}catch(e){error.value=e.message}finally{mfaPromptBusy.value=false}}
async function uploadPortalBrand(event){const file=event.target.files?.[0];if(!file)return;error.value='';if(file.size>1024*1024){error.value='Portal image must be under 1 MB';event.target.value='';return}portalBrandBusy.value=true;try{const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read image'));reader.readAsDataURL(file)});portalBrand.value=await api('/settings/portal-branding/image',{method:'PUT',body:{mimeType:file.type,base64:String(dataUrl).split(',')[1]}});message.value='Portal image updated'}catch(e){error.value=e.message}finally{portalBrandBusy.value=false;event.target.value=''}}
async function removePortalBrand(){portalBrandBusy.value=true;error.value='';try{portalBrand.value=await api('/settings/portal-branding/image',{method:'DELETE'});message.value='Portal image removed'}catch(e){error.value=e.message}finally{portalBrandBusy.value=false}}
async function uploadAvatar(event){const file=event.target.files?.[0];if(!file)return;error.value='';if(file.size>512*1024){error.value='Avatar must be under 512 KB';return}uploadingAvatar.value=true;try{const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read image'));reader.readAsDataURL(file)});await api(`/users/${session.user.id}/avatar`,{method:'PUT',body:{mimeType:file.type,base64:String(dataUrl).split(',')[1]}});me.value=await api('/auth/me');message.value='Avatar updated'}catch(e){error.value=e.message}finally{uploadingAvatar.value=false;event.target.value=''}}
async function changeEmail(){try{await api(`/users/${session.user.id}/profile`,{method:'PATCH',body:{email:newEmail.value}});message.value='Verification sent to the new address';newEmail.value=''}catch(e){error.value=e.message}}
async function changePassword(){error.value='';if(newPassword.value!==confirmPassword.value){error.value='New passwords do not match';return}try{await api(`/users/${session.user.id}/profile`,{method:'PATCH',body:{currentPassword:currentPassword.value,password:newPassword.value}});session.clear();location.assign('/login')}catch(e){error.value=e.message}}
async function saveTheme(){error.value='';try{const profile=await api(`/users/${session.user.id}/profile`,{method:'PATCH',body:{theme:serverTheme.value}});serverTheme.value=profile.theme;applyTheme(profile.theme);message.value='Account theme saved'}catch(e){error.value=e.message}}
function changeBrowserTheme(){setLocalTheme(browserTheme.value)}
async function resendVerification(){try{await api('/auth/email-verification/request',{method:'POST',body:{}});message.value='Verification sent to your current address'}catch(e){error.value=e.message}}
onMounted(async()=>{await load();me.value=await api('/auth/me');serverTheme.value=normalizeTheme(me.value.profile?.theme)||'system';browserTheme.value=localTheme();applyTheme(serverTheme.value)})
</script>
<template><div class="view"><PageHeader eyebrow="CONTROL PLANE / SETTINGS" title="Administration" description="Manage credentials, operators, teams and agent enrollment" /><div v-if="error" class="error-msg">{{error}}</div><div v-if="message" class="success-msg">{{message}}</div><div class="admin-layout"><aside class="panel glass admin-nav"><button v-for="name in ['credentials','access','users','teams','agents','training','observability','directory','entra','branding','audit','security']" :key="name" v-show="!['directory','observability','entra','branding'].includes(name)||isAdmin" :class="{active:tab===name}" @click="tab=name"><i class="mdi" :class="`mdi-${({credentials:'key-outline',access:'share-variant-outline',users:'account-multiple-outline',teams:'account-group-outline',agents:'lan-connect',training:'brain',observability:'radar',directory:'domain',entra:'microsoft-azure',branding:'palette-outline',audit:'clipboard-text-clock-outline',security:'shield-key-outline'})[name]}`"></i>{{name}}</button></aside><section class="panel glass admin-content"><template v-if="tab==='security'"><div class="panel-title"><div><span class="eyebrow">MY ACCOUNT</span><h2>Authenticator</h2></div><span class="status" :class="me?.totpEnabled?'reachable':'unknown'">{{me?.totpEnabled?'Enabled':'Disabled'}}</span></div><div class="security-settings"><p>Protect your control plane login with a 6-digit code from an authenticator app.</p><div class="avatar-setting"><img v-if="me?.profile?.avatar_url" :src="me.profile.avatar_url" alt="Your avatar" class="avatar-preview"><div v-else class="avatar-preview avatar-placeholder">{{session.user?.email?.[0]?.toUpperCase()||'W'}}</div><label>Profile image (PNG, JPEG or WebP, up to 512 KB)<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="uploadingAvatar" @change="uploadAvatar"></label></div><form class="inline-form" @submit.prevent="changeEmail"><input v-model="newEmail" type="email" required :placeholder="me?.email||'New email address'" aria-label="New email address"><button class="button small secondary">Change email</button></form><div class="appearance-setting"><h3>Appearance</h3><div class="appearance-controls"><label>Account theme<select v-model="serverTheme"><option value="system">System</option><option value="hacker">Hacker</option><option value="enterprise">Enterprise</option></select></label><button class="button small secondary" @click="saveTheme">Save account theme</button><label>This browser<select v-model="browserTheme" @change="changeBrowserTheme"><option value="system">Use account theme</option><option value="hacker">Hacker override</option><option value="enterprise">Enterprise override</option></select></label></div></div><NotificationPreferences :me="me" /><form class="password-form" @submit.prevent="changePassword"><h3>Change password</h3><label>Current password<input v-model="currentPassword" type="password" autocomplete="current-password" required></label><label>New password<input v-model="newPassword" type="password" autocomplete="new-password" minlength="12" required></label><label>Confirm new password<input v-model="confirmPassword" type="password" autocomplete="new-password" minlength="12" required></label><button class="button small secondary">Change password</button></form><button v-if="me&&!me.emailVerified" class="button small secondary" @click="resendVerification">Resend email verification</button><template v-if="!me?.totpEnabled"><button v-if="!totpSetup" class="button primary" @click="beginTotp">Set up authenticator</button><div v-else class="form-grid"><label>Setup secret<input :value="totpSetup.secret" readonly></label><label>Authenticator URI<input :value="totpSetup.uri" readonly></label><label>Enter current code<input v-model="totpCode" inputmode="numeric" maxlength="6" placeholder="000000"></label><div class="form-actions"><button class="button primary" @click="confirmTotp">Verify and enable</button></div></div></template><div v-else class="form-grid"><label>Current password<input v-model="disablePassword" type="password"></label><label>Authenticator code<input v-model="disableCode" inputmode="numeric" maxlength="6"></label><div class="form-actions"><button class="button danger" @click="removeTotp">Disable authenticator</button></div></div></div></template><template v-else-if="tab==='training'"><div class="panel-title"><div><span class="eyebrow">HOST LIFECYCLE</span><h2>New host training</h2></div><span class="status learning">Automatic</span></div><div class="training-settings"><p>Each node gets a personal learned policy. Policy Studio previews observed rules during training. At the deadline, that policy and assigned group policies are applied and the learned rules stop changing automatically.</p><form class="training-settings-form" @submit.prevent="saveTraining"><label>Default training period (days)<input v-model.number="trainingSettings.newHostTrainingDays" type="number" min="1" max="365" required></label><label class="training-check"><input v-model="trainingSettings.progressiveLearning.enabled" type="checkbox"> Enable progressive learning</label><template v-if="trainingSettings.progressiveLearning.enabled"><label>First apply after (days)<input v-model.number="trainingSettings.progressiveLearning.startDays" type="number" min="1" :max="trainingSettings.newHostTrainingDays-1" required></label><label>Update interval (hours)<input v-model.number="trainingSettings.progressiveLearning.intervalHours" type="number" min="1" max="168" required></label></template><button v-if="isAdmin" class="button primary" :disabled="trainingSaving">{{trainingSaving?'Saving…':'Save training settings'}}</button></form><p class="muted">These defaults apply to new training sessions. Progressive updates create policy versions and stop at the session deadline. Existing deadlines and schedules are unchanged.</p></div></template><template v-else-if="tab==='observability'"><div class="panel-title"><div><span class="eyebrow">DATA LIFECYCLE</span><h2>Logs and DNS</h2></div></div><div class="training-settings"><p>Choose how long security events stay in the database and how often the control plane refreshes each node's DNS records. Retention runs hourly; DNS refresh runs in batches every 15 minutes.</p><form class="training-settings-form" @submit.prevent="saveObservability"><label>Log retention (days)<input v-model.number="observabilitySettings.logRetentionDays" type="number" min="1" max="3650" required></label><label>DNS refresh interval (hours)<input v-model.number="observabilitySettings.dnsRefreshHours" type="number" min="1" max="720" required></label><label>Summarize event patterns every (hours)<input v-model.number="observabilitySettings.eventCompactHours" type="number" min="1" max="720" required></label><label class="training-check"><input v-model="observabilitySettings.hideLoopbackEvents" type="checkbox"> Hide local loopback traffic by default</label><label class="training-check"><input v-model="observabilitySettings.ignoreLoopbackIngest" type="checkbox"> Discard local loopback traffic on ingestion</label><button class="button primary" :disabled="observabilitySaving">{{observabilitySaving?'Saving…':'Save settings'}}</button></form></div></template><template v-else-if="tab==='entra'"><EntraSettings /></template><template v-else-if="tab==='branding'"><div class="panel-title"><div><span class="eyebrow">ACCESS PORTAL</span><h2>Company branding</h2></div></div><div class="branding-settings"><p>Show your company name and image on the MFA access page. The image is served from this control plane.</p><form class="form-grid" @submit.prevent="savePortalBrand"><label>Company name<input v-model.trim="portalBrand.companyName" maxlength="80" required></label><div class="form-actions"><button class="button primary" :disabled="portalBrandBusy">Save company name</button></div></form><div class="portal-brand-preview"><img v-if="portalBrand.imageUrl" :src="portalBrand.imageUrl" alt="MFA portal brand image"><span v-else>No custom image uploaded</span></div><label>Portal image (PNG, JPEG, or WebP, up to 1 MB)<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="portalBrandBusy" @change="uploadPortalBrand"></label><button v-if="portalBrand.imageUrl" class="button small secondary" :disabled="portalBrandBusy" @click="removePortalBrand">Remove image</button><section class="mfa-fallback-settings"><h3>Automatic MFA prompt fallback</h3><p>When a blocked connection comes from a client outside AD inventory, or a known client cannot be reached or authenticated over WinRM, choose how the target responds. Fail open creates a short, source IP scoped firewall grant without MFA. Every grant is audited and expires automatically.</p><form class="form-grid" @submit.prevent="saveMfaPromptSettings"><label>Client control failure<select v-model="mfaPromptSettings.failureMode"><option value="closed">Fail closed (recommended)</option><option value="open">Fail open temporarily</option></select></label><label v-if="mfaPromptSettings.failureMode==='open'">Fallback grant duration (minutes)<input v-model.number="mfaPromptSettings.failOpenMinutes" type="number" min="2" max="15" required></label><label v-if="mfaPromptSettings.failureMode==='open'">Approval when enabling<input v-model.trim="mfaPromptApproval" placeholder="ENABLE MFA FAIL OPEN"></label><div class="form-actions"><button class="button primary" :disabled="mfaPromptBusy">Save fallback setting</button></div></form><p class="muted">A client with no matching outbound event or no identifiable active process session remains blocked. Disconnected sessions are never prompted.</p></section><EventExportSettings v-if="isAdmin" /></div></template><template v-else-if="tab==='directory'"><div class="panel-title"><div><span class="eyebrow">INVENTORY SOURCE</span><h2>Active Directory</h2></div><span class="status" :class="directorySettings.lastSyncStatus==='failed'?'unreachable':directorySettings.enabled?'reachable':'unknown'">{{directorySettings.lastSyncStatus==='failed'?'Needs attention':directorySettings.enabled?'Scheduled':'Disabled'}}</span></div><div class="directory-settings"><p>Use a read-only directory account from the credential vault to discover computer objects. LDAPS certificate validation is required. Discovered hosts enter new-host training when enabled in AD.</p><form class="directory-form" @submit.prevent="saveDirectory()"><label>LDAPS server URL<input v-model.trim="directorySettings.url" type="url" required placeholder="ldaps://dc.example.com:636/"></label><label>Search base DN<input v-model.trim="directorySettings.baseDn" required placeholder="DC=example,DC=com"></label><label>Directory bind credential<select v-model="directorySettings.bindCredentialId" required><option value="">Select vault credential</option><option v-for="credential in credentials" :key="credential.id" :value="credential.id">{{credential.name}} · {{credential.username}}</option></select></label><label>WinRM credential for discovered nodes<select v-model="directorySettings.nodeCredentialId"><option :value="null">Assign later</option><option v-for="credential in credentials" :key="credential.id" :value="credential.id">{{credential.name}}</option></select></label><label>Sync interval (minutes)<input v-model.number="directorySettings.syncIntervalMinutes" type="number" min="5" max="1440" required></label><label class="directory-toggle"><input v-model="directorySettings.enabled" type="checkbox"> Enable scheduled inventory sync</label><div class="directory-fallback-control"><label class="directory-fallback-toggle"><input v-model="directorySettings.allowLdapFallback" type="checkbox"> Allow LDAP 389 fallback when LDAPS cannot connect</label><p>Administrator approval is required. LDAP 389 simple bind sends the directory credential without TLS. Use a dedicated read-only account on a trusted network. Certificate validation failures will never trigger fallback.</p><label v-if="fallbackApprovalRequired">Type ALLOW LDAP 389 to approve this server and bind credential<input v-model.trim="directoryApproval" type="text" autocomplete="off" placeholder="ALLOW LDAP 389" required></label><small v-else-if="directorySettings.allowLdapFallback">Approved {{directorySettings.ldapFallbackApprovedAt?new Date(directorySettings.ldapFallbackApprovedAt).toLocaleString():''}}</small></div><div class="directory-actions"><button class="button primary" :disabled="directoryBusy">Save connection</button><button type="button" class="button secondary" :disabled="directoryBusy" @click="testDirectory">Test connection</button><button type="button" class="button secondary" :disabled="directoryBusy||!directorySettings.enabled" @click="syncDirectoryNow">Sync computers now</button></div></form><div class="directory-action-credential"><h3>AD account controls</h3><p>Use a separate delegated credential for account enable/disable. Changes require certificate-validated LDAPS and are audited. Temporary disables are re-enabled only if the AD flags still match WinFire's change.</p><label>Account-control credential<select v-model="directorySettings.actionCredentialId"><option :value="null">Disabled</option><option v-for="credential in credentials" :key="credential.id" :value="credential.id">{{credential.name}} · {{credential.username}}</option></select></label><button class="button small secondary" :disabled="directoryBusy" @click="saveDirectoryActionCredential">Save account-control credential</button></div><div class="directory-status"><strong>Last sync: {{directorySettings.lastSyncStatus||'Never'}}</strong><span>{{directorySettings.lastSyncedAt?new Date(directorySettings.lastSyncedAt).toLocaleString():'No successful sync yet'}} · {{directorySettings.lastSyncCount??0}} computers</span><small v-if="directorySettings.lastTransport">Last successful transport: {{directorySettings.lastTransport==='ldap'?'LDAP 389 approved fallback':'LDAPS'}}</small><small v-if="directorySettings.lastSyncError" class="danger-text">{{directorySettings.lastSyncError}}</small><small v-if="directoryResult?.found!==undefined">Latest run: {{directoryResult.created}} added, {{directoryResult.updated}} updated, {{directoryResult.missing}} missing from AD.</small></div><p class="muted">Directory sync never deletes a node or its policies. Trust the domain controller certificate with the server OS or NODE_EXTRA_CA_CERTS. Account control actions require separate review and are not enabled here.</p></div></template><template v-else-if="tab==='access'"><ResourceGrants /></template><template v-else-if="tab==='credentials'"><div class="panel-title"><div><span class="eyebrow">SECRET STORE</span><h2>Credential vault</h2></div><button class="button small primary" @click="formOpen=true"><i class="mdi mdi-plus"></i> Add credential</button></div><div class="table-wrap"><table><thead><tr><th>NAME</th><th>TYPE</th><th>USERNAME</th><th>VISIBILITY</th><th>PRIORITY</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="credential in credentials" :key="credential.id"><td><i class="mdi mdi-key-outline"></i> {{credential.name}}</td><td>{{credential.type}}</td><td class="mono">{{credential.username}}</td><td>{{credential.visibility}}</td><td>{{credential.priority}}</td><td><button class="button small secondary" @click="openCredential(credential)">Manage</button></td></tr><tr v-if="!credentials.length"><td colspan="6" class="empty-table">No credentials stored. Add one before connecting to a node.</td></tr></tbody></table></div></template><template v-else-if="tab==='users'"><div class="panel-title"><div><span class="eyebrow">ACCESS CONTROL</span><h2>Operators</h2></div></div><div class="table-wrap"><table><thead><tr><th>EMAIL</th><th>ROLE</th><th>STATUS</th><th>CREATED</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td>{{user.email}}</td><td>{{user.role}}</td><td><span class="status" :class="user.suspended?'unreachable':'reachable'">{{user.suspended?'Suspended':'Active'}}</span></td><td>{{new Date(user.created_at).toLocaleDateString()}}</td><td><div v-if="canManageUser(user)" class="user-actions"><button class="button small secondary" @click="revokeSessions(user)">Revoke sessions</button><button class="button small secondary" @click="setSuspended(user)">{{user.suspended?'Restore':'Suspend'}}</button><button v-if="session.user?.role==='owner'" class="button small danger" @click="confirmDeleteUser(user)">Delete</button></div></td></tr></tbody></table></div><form v-if="isAdmin" class="inline-form" @submit.prevent="createUser"><input v-model="userForm.email" type="email" required placeholder="New user's email"><input v-model="userForm.password" type="password" minlength="12" required placeholder="Temporary password"><select v-model="userForm.role"><option>auditor</option><option>editor</option><option>admin</option></select><button class="button small primary">Create user</button></form><div v-if="isAdmin" class="panel-title"><div><span class="eyebrow">ONBOARDING</span><h2>Invitations</h2></div></div><form v-if="isAdmin" class="inline-form" @submit.prevent="createInvite"><input v-model="inviteForm.email" type="email" required placeholder="Invitee email"><select v-model="inviteForm.role"><option>auditor</option><option>editor</option><option>admin</option><option v-if="session.user?.role==='owner'">owner</option></select><select v-model="inviteForm.teamId"><option value="">No team</option><option v-for="team in teams" :key="team.id" :value="team.id">{{team.name}}</option></select><button class="button small primary">Invite</button></form><div v-if="inviteResult?.inviteUrl" class="code-block">{{inviteResult.inviteUrl.startsWith('http')?inviteResult.inviteUrl:origin+inviteResult.inviteUrl}}<small>Share this link with {{inviteResult.email}}. It expires in seven days.</small></div><div v-if="invites.length" class="table-wrap"><table><thead><tr><th>EMAIL</th><th>ROLE</th><th>DELIVERY</th><th>STATUS</th></tr></thead><tbody><tr v-for="invite in invites" :key="invite.id"><td>{{invite.email}}</td><td>{{invite.role}}</td><td>{{invite.delivered_at?'Emailed':'Manual link'}}</td><td>{{invite.accepted_at?'Accepted':new Date(invite.expires_at)<new Date()?'Expired':'Pending'}}</td></tr></tbody></table></div></template><template v-else-if="tab==='teams'"><div class="panel-title"><div><span class="eyebrow">ORGANIZATION</span><h2>Teams</h2></div></div><div v-for="team in teams" :key="team.id" class="segment-row"><div class="segment-icon"><i class="mdi mdi-account-group-outline"></i></div><strong>{{team.name}}</strong></div><div v-if="!teams.length" class="empty-side">No teams created.</div><form v-if="isAdmin" class="inline-form" @submit.prevent="createTeam"><input v-model="teamName" required placeholder="New team name"><button class="button small primary">Create team</button></form></template><template v-else-if="tab==='agents'"><div class="panel-title"><div><span class="eyebrow">ENDPOINT CONNECTIVITY</span><h2>Agents</h2></div></div><div v-for="agent in agents" :key="agent.id" class="segment-row"><div class="segment-icon"><i class="mdi mdi-lan-connect"></i></div><div><strong>{{nodes.find(n=>n.id===agent.node_id)?.hostname||agent.node_id}}</strong><small>{{agent.version}} · {{agent.mode}} · {{agent.last_checkin_at||'Never checked in'}} · {{agent.revoked_at?'Revoked':'Active'}}</small></div><button v-if="isAdmin&&!agent.revoked_at" class="button small danger" @click="revokeAgent(agent)">Revoke</button></div><div v-if="!agents.length" class="empty-side">No agents enrolled.</div><div v-if="isAdmin" class="inline-form"><select v-model="enrollNode"><option value="">Select node for token</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{node.hostname}}</option></select><button class="button small secondary" :disabled="!enrollNode" @click="createToken">Generate token</button></div><div v-if="token" class="code-block">{{token.token}}<small>Expires {{new Date(token.expiresAt).toLocaleString()}}</small></div><p class="muted">Certificate backed enrollment and MSI distribution require Windows packaging and PKI setup.</p></template><template v-else><div class="panel-title"><div><span class="eyebrow">CHANGE HISTORY</span><h2>Audit trail</h2></div><span class="count-chip">{{auditTotal}} entries</span></div><form class="audit-controls" @submit.prevent="auditSearch"><input v-model.trim="auditFilters.q" placeholder="Search action, entity or actor" aria-label="Search audit trail"><input v-model.trim="auditFilters.action" placeholder="Action" aria-label="Filter action"><input v-model.trim="auditFilters.entityType" placeholder="Entity type" aria-label="Filter entity type"><input v-model.trim="auditFilters.actor" placeholder="Actor" aria-label="Filter actor"><label>From<input v-model="auditFilters.from" type="datetime-local"></label><label>To<input v-model="auditFilters.to" type="datetime-local"></label><button class="button small primary" :disabled="auditLoading">Search</button><label>Rows<select v-model.number="auditPageSize" @change="auditSearch"><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option><option :value="250">250</option></select></label><button type="button" class="button small secondary" @click="exportAudit('csv')">CSV</button><button type="button" class="button small secondary" @click="exportAudit('pdf')">PDF</button><button type="button" class="button small secondary" @click="exportAudit('xls')">XLS</button></form><div class="table-wrap"><table><thead><tr><th><button class="audit-sort" @click="auditSort('time')">TIME ↕</button></th><th><button class="audit-sort" @click="auditSort('action')">ACTION ↕</button></th><th><button class="audit-sort" @click="auditSort('entity')">ENTITY ↕</button></th><th><button class="audit-sort" @click="auditSort('actor')">ACTOR ↕</button></th></tr></thead><tbody><tr v-for="entry in audit" :key="entry.id"><td>{{new Date(entry.at).toLocaleString()}}</td><td class="mono">{{entry.action}}</td><td>{{entry.entity_type}} / {{entry.entity_id?.slice(0,8)}}</td><td class="mono">{{entry.actor_email||'system'}}</td></tr><tr v-if="!audit.length"><td colspan="4" class="empty-table">{{auditLoading?'Loading…':'No audited actions match these filters.'}}</td></tr></tbody></table></div><div class="audit-pagination"><span>Page {{auditPage}} of {{auditPages}} · {{auditTotal}} entries</span><div><button class="button small secondary" :disabled="auditPage<=1||auditLoading" @click="auditMove(auditPage-1)">Previous</button><button class="button small secondary" :disabled="auditPage>=auditPages||auditLoading" @click="auditMove(auditPage+1)">Next</button></div></div></template></section></div><GlassWindow v-model="formOpen" title="Add credential"><form class="form-grid" @submit.prevent="createCredential"><label>Name<input v-model="credentialForm.name" required placeholder="Domain service account"></label><label>Type<select v-model="credentialForm.type"><option value="local">Local</option><option value="domain">Domain</option></select></label><label>Username<input v-model="credentialForm.username" required placeholder="DOMAIN\service"></label><label>Password<input v-model="credentialForm.password" type="password" required autocomplete="new-password"></label><label>Visibility<select v-model="credentialForm.visibility"><option value="private">Private</option><option value="team">Team</option></select></label><label>Priority<input v-model.number="credentialForm.priority" type="number"></label><div class="form-actions"><button class="button primary">Store credential</button></div></form></GlassWindow><GlassWindow v-model="credentialWindowOpen" :title="`Manage ${selectedCredential?.name||'credential'}`" width="560px"><div class="credential-management"><p>Use this vault entry on a Windows node or node group. The password remains write-only.</p><div class="form-grid"><label>Target type<select v-model="credentialTargetKind"><option value="node">Node</option><option value="group">Node group</option></select></label><label v-if="credentialTargetKind==='node'">Node<select v-model="credentialNodeId" @change="credentialTestResult=null"><option value="">Select node</option><option v-for="node in nodes.filter(item=>item.connection_mode==='agentless')" :key="node.id" :value="node.id">{{node.hostname}}</option></select></label><label v-else>Node group<select v-model="credentialGroupId"><option value="">Select group</option><option v-for="group in nodeGroups" :key="group.id" :value="group.id">{{group.name}}</option></select></label></div><div class="inline-actions"><button class="button small secondary" :disabled="credentialBusy||!(credentialTargetKind==='node'?credentialNodeId:credentialGroupId)" @click="assignCredential">Assign credential</button><button v-if="credentialTargetKind==='node'" class="button small secondary" :disabled="credentialBusy||!credentialNodeId" @click="testCredential">Test authentication</button></div><p v-if="credentialTestResult" :class="credentialTestResult.success?'success-msg':'error-msg'">{{credentialTestResult.success?`${credentialTestResult.transport==='wmi'?'WMI/DCOM':'WinRM'} authenticated as ${credentialTestResult.account}${credentialTestResult.computerName?` on ${credentialTestResult.computerName}`:''}`:credentialTestResult.error}}</p><form v-if="canManageCredential(selectedCredential)" class="credential-rotate" @submit.prevent="rotateCredential"><h3>Rotate password</h3><label>New password<input v-model="credentialNewPassword" type="password" autocomplete="new-password" required></label><button class="button small primary" :disabled="credentialBusy">Rotate password</button></form></div></GlassWindow><GlassWindow v-model="deleteConfirmOpen" title="Delete operator" width="480px"><p>Delete {{userToDelete?.email}} and revoke their access permanently?</p><div class="form-actions"><button class="button secondary" @click="deleteConfirmOpen=false">Cancel</button><button class="button danger" @click="deleteUser">Delete operator</button></div></GlassWindow></div></template>
